// Tests for the Android registry export (Step 1 of the Android data
// programme). The export is generated by
// apps/web/scripts/generate-android-registry.mjs from the web wallet's
// TypeScript sources; these tests check the committed JSON against those
// sources — never against the generator's own word.
//
// Method: the counts and spot values are read TEXTUALLY from the .ts
// sources here (regexes over the file text), independently of the
// generator's TypeScript-compiler loading, so the generator and the
// test can only agree when both read the same truth. Pinned counts
// (74 explorers, 85 templates, 81 address formats, 57 curves, 80
// second price sources, 7 CoinGecko-alone chains, 169 RPCs) are
// asserted with the arithmetic that derives them in the comment above
// each assertion — a count that moves must move in the source first.
//
// Prerequisite: apps/web/node_modules must be installed (the
// determinism and --check tests load the generator, which transpiles
// the wallet sources through the TypeScript compiler there). In CI
// these run in the `web` job after `npm ci`.
import { describe, test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = fileURLToPath(new URL('../', import.meta.url));
const registryDir = path.join(repoRoot, 'registry');
const walletDir = path.join(repoRoot, 'apps', 'web', 'src', 'wallet');
const generatorPath = path.join(
  repoRoot,
  'apps',
  'web',
  'scripts',
  'generate-android-registry.mjs',
);

function readJson(file) {
  return JSON.parse(readFileSync(file, 'utf8'));
}

function readText(file) {
  return readFileSync(file, 'utf8');
}

const chainsDoc = readJson(path.join(registryDir, 'chains.json'));
const tokensDoc = readJson(path.join(registryDir, 'tokens.json'));
const capabilities = readJson(path.join(registryDir, 'capabilities.json'));

// --- textual reads of the TS sources (independent of the generator) ---
const chainsText = readText(path.join(walletDir, 'chains.ts'));
const chainsBlock = chainsText.slice(
  chainsText.indexOf('export const CHAINS'),
  chainsText.indexOf('export const SUPPORTED_CHAINS'),
);
const genFactsBlock = chainsText.slice(
  chainsText.indexOf('export const GENERATED_CHAIN_FACTS'),
  chainsText.indexOf('// END GENERATED CHAIN FACTS'),
);
// Top-level CHAINS keys are the 2-space-indented `id: {` lines.
const chainKeys = [...chainsBlock.matchAll(/^  ([a-z0-9]+): \{$/gm)].map(
  (match) => match[1],
);
const supportedMatch = /export const SUPPORTED_CHAINS[^=]*= \[([\s\S]*?)\];/.exec(chainsText);
assert.ok(supportedMatch, 'SUPPORTED_CHAINS not found in chains.ts');
const supportedChains = [...supportedMatch[1].matchAll(/'([a-z0-9]+)'/g)].map(
  (match) => match[1],
);
const rpcUrlsIn = (text) =>
  [...text.matchAll(/rpcEndpoints: \[([\s\S]*?)\]/g)].reduce(
    (count, match) => count + (match[1].match(/'https?:\/\/[^']+'/g) ?? []).length,
    0,
  );
// 83 literal rpcEndpoints arrays in the CHAINS block plus the 4 spread
// GENERATED_CHAIN_FACTS entries (btc/eth/trx/ton).
const rpcTotalFromSource = rpcUrlsIn(chainsBlock) + rpcUrlsIn(genFactsBlock);

const tokensText = readText(path.join(walletDir, 'tokens.ts'));
const tokensBlock = tokensText.slice(
  tokensText.indexOf('export const DEFAULT_TOKENS'),
  tokensText.indexOf('export const EVM_TOKEN_CHAINS'),
);
const defaultTokenCount = (
  tokensBlock.match(/chain: '[a-z0-9]+',\s*\n\s*contract: '/g) ?? []
).length;

const expandedText = readText(path.join(walletDir, 'chains-expanded.ts'));
const expandedKeys = [...expandedText.matchAll(/key: "([a-z0-9]+)"/g)].map(
  (match) => match[1],
);

const watchOnlyText = readText(path.join(walletDir, 'watch-only-families.ts'));
const evmWatchStart = watchOnlyText.indexOf('export const EVM_WATCH_CHAINS');
const evmWatchBlock = watchOnlyText.slice(
  evmWatchStart,
  watchOnlyText.indexOf('] as const;', evmWatchStart),
);
const evmWatchChains = [...evmWatchBlock.matchAll(/'([a-z0-9]+)'/g)].map(
  (match) => match[1],
);

const detectionText = readText(path.join(walletDir, 'address-detection.ts'));
const patternChains = [
  ...new Set(
    [...detectionText.matchAll(/, '([a-z0-9]+)', '[^']+'\],/g)].map(
      (match) => match[1],
    ),
  ),
];

function expandedField(key, field) {
  const start = expandedText.indexOf(`key: "${key}"`);
  assert.ok(start !== -1, `expanded chain ${key} not found`);
  const slice = expandedText.slice(start, start + 4000);
  const match = new RegExp(`${field}: "([^"]+)"`).exec(slice);
  assert.ok(match, `expanded field ${field} not found for ${key}`);
  return match[1];
}

describe('android registry export', () => {
  test('chains.json header and version', () => {
    assert.equal(chainsDoc.registry, 'chains');
    assert.equal(chainsDoc.version, 1);
    assert.match(chainsDoc.generated, /DO NOT EDIT BY HAND/);
    assert.equal(chainsDoc.generator, 'node apps/web/scripts/generate-android-registry.mjs');
    assert.match(chainsDoc.sourceCommit ?? '', /^[0-9a-f]{40}$/);
    assert.equal(typeof chainsDoc.sourceDirty, 'boolean');
    assert.equal(typeof chainsDoc.generatedAt, 'string');
    assert.ok(!Number.isNaN(Date.parse(chainsDoc.generatedAt)));
  });

  test('tokens.json header and version', () => {
    assert.equal(tokensDoc.registry, 'tokens');
    assert.equal(tokensDoc.version, 1);
    assert.match(tokensDoc.generated, /DO NOT EDIT BY HAND/);
    assert.equal(tokensDoc.generator, 'node apps/web/scripts/generate-android-registry.mjs');
    assert.equal(tokensDoc.sourceCommit, chainsDoc.sourceCommit);
    assert.equal(tokensDoc.sourceDirty, chainsDoc.sourceDirty);
  });

  test('87 chains: ids match the TS sources', () => {
    assert.equal(chainKeys.length, 87);
    assert.equal(supportedChains.length, 87);
    assert.deepEqual([...chainKeys].sort(), [...supportedChains].sort());
    assert.equal(chainsDoc.chainCount, 87);
    assert.equal(chainsDoc.chains.length, 87);
    assert.deepEqual(
      chainsDoc.chains.map((entry) => entry.id),
      supportedChains,
      'chains.json order follows SUPPORTED_CHAINS',
    );
    assert.equal(new Set(chainsDoc.chains.map((entry) => entry.id)).size, 87);
  });

  test('65 expanded chains plus 22 curated chains make the 87', () => {
    assert.equal(expandedKeys.length, 65);
    assert.equal(new Set(expandedKeys).size, 65);
    for (const key of expandedKeys) {
      assert.ok(
        supportedChains.includes(key),
        `expanded chain ${key} is not in SUPPORTED_CHAINS`,
      );
    }
    const curated = supportedChains.filter((id) => !expandedKeys.includes(id));
    assert.equal(curated.length, 22);
    assert.deepEqual([...curated].sort(), [
      'arb', 'aurora', 'avax', 'base', 'bsc', 'btc', 'celo', 'doge', 'eth',
      'fantom', 'gnosis', 'linea', 'ltc', 'mantle', 'matic', 'metis', 'op',
      'opbnb', 'scroll', 'sol', 'ton', 'trx',
    ]);
  });

  test('every chain in chains.json is in chainSupport and vice versa', () => {
    const supportIds = Object.keys(capabilities.chainSupport);
    assert.equal(supportIds.length, 87);
    assert.deepEqual(
      [...chainsDoc.chains.map((entry) => entry.id)].sort(),
      [...supportIds].sort(),
    );
  });

  test('21 tokens: count and identity match the TS source', () => {
    assert.equal(defaultTokenCount, 21);
    assert.equal(tokensDoc.tokenCount, 21);
    assert.equal(tokensDoc.tokens.length, 21);
    const keys = tokensDoc.tokens.map((entry) => entry.tokenKey);
    assert.equal(new Set(keys).size, 21);
    const chainIds = new Set(chainsDoc.chains.map((entry) => entry.id));
    for (const entry of tokensDoc.tokens) {
      assert.ok(chainIds.has(entry.chain), `token on unknown chain ${entry.chain}`);
      assert.equal(entry.verifiedSource, 'curated');
      assert.ok(entry.coingeckoId, `token ${entry.tokenKey} has no CoinGecko id`);
      assert.ok(entry.coingeckoPlatform, `token ${entry.tokenKey} has no CoinGecko platform`);
      assert.equal(entry.priceSource, 'coingecko');
      assert.ok(entry.priceFallback === 'dexscreener' || entry.priceFallback === 'tonapi');
    }
    assert.equal(tokensDoc.coverage.chains, 10);
    assert.equal(tokensDoc.coverage.withCoingeckoId, 21);
    assert.equal(tokensDoc.coverage.withPriceFallback, 21);
  });

  test('RPC total matches the TS source (169 endpoints)', () => {
    assert.equal(rpcTotalFromSource, 169);
    assert.equal(chainsDoc.coverage.rpcEndpoints, 169);
    const total = chainsDoc.chains.reduce(
      (sum, entry) => sum + entry.rpcEndpoints.length,
      0,
    );
    assert.equal(total, 169);
    for (const entry of chainsDoc.chains) {
      assert.ok(entry.rpcEndpoints.length >= 1, `${entry.id} has no RPC`);
      for (const url of entry.rpcEndpoints) {
        assert.ok(url.startsWith('https://'), `${entry.id} RPC is not https: ${url}`);
      }
      assert.equal(new Set(entry.rpcEndpoints).size, entry.rpcEndpoints.length);
    }
  });

  test('derivation templates match the expanded facts; SOL/TON have none', () => {
    // 85 of 87 chains carry a single template; Solana and TON use the
    // Ed25519 scheme, which changes shape with account/index.
    assert.equal(chainsDoc.coverage.chainsWithDerivationTemplate, 85);
    const noTemplate = chainsDoc.chains
      .filter((entry) => entry.derivationTemplate === null)
      .map((entry) => entry.id);
    assert.deepEqual([...noTemplate].sort(), ['sol', 'ton']);
    for (const entry of chainsDoc.chains) {
      assert.ok(entry.derivationPath.startsWith('m/'), `${entry.id} derivationPath`);
      if (entry.derivationTemplate !== null) {
        assert.match(entry.derivationTemplate, /\{account\}/);
      } else {
        assert.match(entry.notes ?? '', /Ed25519/);
      }
    }
    for (const key of ['zksync', 'filecoin', 'cosmos', 'cardano', 'stellar', 'kaspa', 'starknet']) {
      const entry = chainsDoc.chains.find((item) => item.id === key);
      assert.equal(
        entry.derivationTemplate,
        expandedField(key, 'derivationTemplate'),
        `${key} template disagrees with chains-expanded.ts`,
      );
      assert.equal(
        entry.derivationPath,
        expandedField(key, 'derivationPath'),
        `${key} account-0 path disagrees with chains-expanded.ts`,
      );
      assert.equal(entry.explorerUrl, expandedField(key, 'explorerBaseUrl'));
    }
  });

  test('explorers: 74 of 87 chains have one (19 in CHAINS + 65 expanded − 10 overlap)', () => {
    assert.equal(chainsDoc.coverage.chainsWithExplorer, 74);
    const eth = chainsDoc.chains.find((entry) => entry.id === 'eth');
    assert.equal(eth.explorerUrl, 'https://eth.blockscout.com');
    const btc = chainsDoc.chains.find((entry) => entry.id === 'btc');
    assert.equal(btc.explorerUrl, null);
    assert.match(btc.notes ?? '', /No explorer URL/);
  });

  test('address formats: 81 of 87 chains (59 EVM 0x + 22 detection-table chains)', () => {
    assert.equal(evmWatchChains.length, 59);
    assert.equal(patternChains.length, 22);
    assert.equal(chainsDoc.coverage.chainsWithAddressFormat, 81);
    const expectedNull = supportedChains.filter(
      (id) => !evmWatchChains.includes(id) && !patternChains.includes(id),
    );
    assert.deepEqual([...expectedNull].sort(), [
      'algorand', 'aptos', 'cardano', 'kaspa', 'near', 'starknet',
    ]);
    const actualNull = chainsDoc.chains
      .filter((entry) => entry.addressFormat === null)
      .map((entry) => entry.id);
    assert.deepEqual([...actualNull].sort(), [...expectedNull].sort());
    const eth = chainsDoc.chains.find((entry) => entry.id === 'eth');
    assert.equal(eth.addressFormat.kind, 'evm');
    assert.deepEqual(eth.addressFormat.patterns, ['^0x[0-9a-fA-F]{40}$']);
    const btc = chainsDoc.chains.find((entry) => entry.id === 'btc');
    assert.equal(btc.addressFormat.kind, 'chain');
    assert.equal(btc.addressFormat.patterns.length, 2);
    for (const pattern of btc.addressFormat.patterns) {
      assert.doesNotThrow(() => new RegExp(pattern));
    }
  });

  test('Trust Wallet coin numbers: 87 of 87; curves: 57 of 87 (the coins table)', () => {
    assert.equal(chainsDoc.coverage.chainsWithTrustWalletCoinType, 87);
    assert.equal(chainsDoc.coverage.chainsWithCurve, 57);
    const zksync = chainsDoc.chains.find((entry) => entry.id === 'zksync');
    assert.equal(zksync.trustWalletCoinType, 10000324);
    assert.equal(zksync.coinType, 60);
    assert.equal(zksync.curve, 'secp256k1');
    const cardano = chainsDoc.chains.find((entry) => entry.id === 'cardano');
    assert.equal(cardano.trustWalletCoinType, 1815);
    assert.equal(cardano.coinType, 1815);
    assert.equal(cardano.curve, null);
    const sol = chainsDoc.chains.find((entry) => entry.id === 'sol');
    assert.equal(sol.trustWalletCoinType, 501);
    assert.equal(sol.curve, 'ed25519');
  });

  test('SLIP-44: derivation coin vs registered number (they differ on 5 EVM chains)', () => {
    // The derivation coin (coinType) is 60 for every EVM chain on the
    // Ethereum path; the registered number (assetSlip44, from assetId)
    // is the chain's own — 714 BSC, 966 Polygon, 9000 Avalanche, 527
    // Celo, 250 Fantom. Both are real; the export carries both.
    const differing = chainsDoc.chains
      .filter((entry) => entry.coinType !== entry.assetSlip44)
      .map((entry) => [entry.id, entry.coinType, entry.assetSlip44])
      .sort((a, b) => (a[0] < b[0] ? -1 : 1));
    assert.deepEqual(differing, [
      ['avax', 60, 9000],
      ['bsc', 60, 714],
      ['celo', 60, 527],
      ['fantom', 60, 250],
      ['matic', 60, 966],
    ]);
    for (const entry of chainsDoc.chains.filter(
      (item) => item.coinType !== item.assetSlip44,
    )) {
      assert.match(entry.notes ?? '', /registered SLIP-44 number in assetId is \d+/);
    }
    for (const entry of chainsDoc.chains) {
      const assetMatch = /\/slip44:(\d+)$/.exec(entry.assetId);
      assert.ok(assetMatch, `${entry.id} assetId has no slip44 segment`);
      assert.equal(entry.assetSlip44, Number(assetMatch[1]));
      if (entry.derivationTemplate === null) {
        assert.equal(entry.coinType, entry.assetSlip44);
      } else {
        const templateMatch = /^m\/\d+'\/(\d+)'/.exec(entry.derivationTemplate);
        assert.ok(templateMatch, `${entry.id} template has no coin segment`);
        assert.equal(entry.coinType, Number(templateMatch[1]));
      }
    }
  });

  test('price sources: 80 of 87 have a second source; 7 are CoinGecko-alone', () => {
    assert.equal(chainsDoc.coverage.chainsWithSecondPriceSource, 80);
    assert.deepEqual([...chainsDoc.coverage.coingeckoAloneChains].sort(), [
      'fraxtal', 'pulsechain', 'rootstock', 'songbird', 'telos', 'velas', 'xdc',
    ]);
    for (const entry of chainsDoc.chains) {
      assert.equal(entry.priceSources[0], 'CoinGecko');
      assert.ok(entry.coingeckoId);
    }
    const ton = chainsDoc.chains.find((entry) => entry.id === 'ton');
    assert.deepEqual(ton.priceSources, ['CoinGecko', 'TonAPI']);
  });

  test('testnets: the 4 devnet networks, clearly marked testnet', () => {
    assert.equal(chainsDoc.testnets.length, 4);
    assert.deepEqual(
      chainsDoc.testnets.map((entry) => entry.id),
      ['btc', 'eth', 'trx', 'ton'],
    );
    for (const entry of chainsDoc.testnets) {
      assert.equal(entry.network, 'testnet');
    }
    const eth = chainsDoc.testnets.find((entry) => entry.id === 'eth');
    assert.equal(eth.devnetName, 'Ethereum Sepolia');
    assert.equal(eth.evmChainId, 11155111);
    assert.equal(eth.rpcUrl, 'https://ethereum-sepolia-rpc.publicnode.com');
  });

  test('generated JSON validates against the schemas', async () => {
    const { validateAgainstSchema } = await import(generatorPath);
    const chainsSchema = readJson(
      path.join(registryDir, 'schemas', 'chains.schema.json'),
    );
    const tokensSchema = readJson(
      path.join(registryDir, 'schemas', 'tokens.schema.json'),
    );
    assert.deepEqual(validateAgainstSchema(chainsDoc, chainsSchema), []);
    assert.deepEqual(validateAgainstSchema(tokensDoc, tokensSchema), []);
  });

  test('schema validator rejects bad documents', async () => {
    const { validateAgainstSchema } = await import(generatorPath);
    const chainsSchema = readJson(
      path.join(registryDir, 'schemas', 'chains.schema.json'),
    );
    const missingField = JSON.parse(JSON.stringify(chainsDoc));
    delete missingField.chains[0].id;
    assert.ok(validateAgainstSchema(missingField, chainsSchema).length > 0);
    const badVersion = JSON.parse(JSON.stringify(chainsDoc));
    badVersion.version = 0;
    assert.ok(validateAgainstSchema(badVersion, chainsSchema).length > 0);
    const extraField = JSON.parse(JSON.stringify(chainsDoc));
    extraField.surprise = true;
    assert.ok(validateAgainstSchema(extraField, chainsSchema).length > 0);
    const badRpc = JSON.parse(JSON.stringify(chainsDoc));
    badRpc.chains[0].rpcEndpoints = ['http://plain.example/rpc'];
    assert.ok(validateAgainstSchema(badRpc, chainsSchema).length > 0);
  });

  test('generator is deterministic (same inputs, same bytes modulo generatedAt)', async () => {
    const { buildRegistry } = await import(generatorPath);
    const fixed = {
      generatedAt: '2026-01-01T00:00:00.000Z',
      stamp: { sourceCommit: '0'.repeat(40), sourceDirty: false },
    };
    const first = await buildRegistry(fixed);
    const second = await buildRegistry(fixed);
    assert.equal(
      JSON.stringify(first.chainsDoc),
      JSON.stringify(second.chainsDoc),
    );
    assert.equal(
      JSON.stringify(first.tokensDoc),
      JSON.stringify(second.tokensDoc),
    );
    assert.equal(first.chainsDoc.chainCount, 87);
    assert.equal(first.tokensDoc.tokenCount, 21);
  });

  test('--check passes on the committed files', () => {
    const result = spawnSync(process.execPath, [generatorPath, '--check'], {
      cwd: repoRoot,
      encoding: 'utf8',
    });
    assert.equal(result.status, 0, result.stderr || result.stdout);
    assert.match(result.stdout, /OK — registry\/chains\.json and registry\/tokens\.json match the sources/);
  });
});
